13	/**
14	 * Get client IP address.
15	 */
16	function getClientIp(): string {
17	    $keys = ['HTTP_X_FORWARDED_FOR', 'HTTP_CLIENT_IP', 'REMOTE_ADDR'];
18	    foreach ($keys as $key) {
19	        if (!empty($_SERVER[$key])) {
20	            $ip = $_SERVER[$key];
21	            if (strpos($ip, ',') !== false) {
22	                $ip = trim(explode(',', $ip)[0]);
23	            }
24	            if (filter_var($ip, FILTER_VALIDATE_IP)) {
25	                return $ip;
26	            }
27	        }
28	    }
29	    return '0.0.0.0';
30	}
