32	/**
33	 * Log a failed login attempt.
34	 */
35	function logFailedLogin(
36	    string $email,
37	    string $attemptType,
38	    ?string $reason = null,
39	    ?string $studentName = null
40	): void {
41	    try {
42	        $pdo = getDB();
43	        $stmt = $pdo->prepare("
44	            INSERT INTO failed_login_log (email, student_name, ip_address, attempt_type, reason)
45	            VALUES (?, ?, ?, ?, ?)
46	        ");
47	        $stmt->execute([
48	            $email,
49	            $studentName,
50	            getClientIp(),
51	            $attemptType,
52	            $reason,
53	        ]);
54	    } catch (Exception $e) {
55	        // Log silently — don't break the auth flow
56	        error_log('Failed to write login log: ' . $e->getMessage());
57	    }
58	}
