62	function adminLogin(string $email, string $password): array {
63	    $pdo = getDB();
64	    $stmt = $pdo->prepare("SELECT * FROM admins WHERE email = ?");
65	    $stmt->execute([$email]);
66	    $admin = $stmt->fetch();
67	
68	    if (!$admin || !password_verify($password, $admin['password_hash'])) {
69	        logFailedLogin($email, 'wrong_password', 'Invalid admin email or password.');
70	        return ['success' => false, 'error' => 'Invalid email or password.'];
71	    }
72	
73	    $_SESSION['admin_id']    = (int)$admin['id'];
74	    $_SESSION['admin_email'] = $admin['email'];
75	    $_SESSION['admin_name']  = $admin['name'] ?? $admin['email'];
76	    $_SESSION['role']        = 'admin';
77	    $_SESSION['admin_role']  = $admin['role'] ?? 'admin';
78	    session_regenerate_id(true);
79	
80	    return ['success' => true];
81	}
