85	/**
86	 * Generate a 6-digit OTP and store hashed version in unverified_students table.
87	 * Returns: ['success' => true, 'otp' => '123456'] or ['success' => false, 'error' => ...]
88	 */
89	function generateStudentOtp(int $studentId, string $email, string $name): array {
90	    $pdo = getDB();
91	
92	    // Generate 6-digit OTP
93	    $otp = str_pad((string)random_int(0, 999999), 6, '0', STR_PAD_LEFT);
94	    $otpHash = password_hash($otp, PASSWORD_BCRYPT);
95	    $expiresAt = date('Y-m-d H:i:s', time() + 600); // 10 minutes
96	
97	    // Store in unverified_students
98	    $stmt = $pdo->prepare("UPDATE unverified_students SET otp_hash = ?, otp_expires_at = ? WHERE id = ?");
99	    $stmt->execute([$otpHash, $expiresAt, $studentId]);
100	
101	    // Send email
102	    require_once __DIR__ . '/mailer.php';
103	    $mailResult = sendOtpEmail($email, $name, $otp);
104	
105	    $result = [
106	        'success'   => $mailResult['success'],
107	        'otp'       => $otp,
108	        'expires_at'=> $expiresAt,
109	        'mail_info' => $mailResult,
110	    ];
111	
112	    // Surface mail error to top level for caller convenience
113	    if (!$mailResult['success'] && isset($mailResult['error'])) {
114	        $result['error'] = $mailResult['error'];
115	    }
116	
117	    return $result;
118	}
