120	/**
121	 * Verify OTP for a student. On success, moves record to students table.
122	 */
123	function verifyStudentOtp(int $studentId, string $otp): array {
124	    $pdo = getDB();
125	
126	    // Fetch from unverified_students
127	    $stmt = $pdo->prepare("SELECT * FROM unverified_students WHERE id = ?");
128	    $stmt->execute([$studentId]);
129	    $student = $stmt->fetch();
130	
131	    if (!$student) {
132	        return ['success' => false, 'error' => 'Student not found or already verified.'];
133	    }
134	
135	    if (empty($student['otp_hash'])) {
136	        logFailedLogin($student['email'], 'signup_unverified', 'No OTP requested. Please register again.', $student['name']);
137	        return ['success' => false, 'error' => 'No OTP requested. Please register again.'];
138	    }
139	
140	    // Check expiry
141	    if (strtotime($student['otp_expires_at']) < time()) {
142	        logFailedLogin($student['email'], 'expired_otp', 'OTP expired.', $student['name']);
143	        return ['success' => false, 'error' => 'OTP expired. Request a new one.', 'expired' => true];
144	    }
145	
146	    // Verify OTP
147	    if (!password_verify($otp, $student['otp_hash'])) {
148	        logFailedLogin($student['email'], 'wrong_otp', 'Invalid OTP entered.', $student['name']);
149	        return ['success' => false, 'error' => 'Invalid OTP. Please try again.'];
150	    }
151	
152	    // ─── OTP CORRECT — Move to students table ───
153	    try {
154	        $pdo->beginTransaction();
155	
156	        $insert = $pdo->prepare("
157	            INSERT INTO students (batch_id, name, phone, email, gender, college_name, branch, roll_number, year_of_joining, course_name, password_hash, created_at)
158	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
159	        ");
160	        $insert->execute([
161	            $student['batch_id'],
162	            $student['name'],
163	            $student['phone'],
164	            $student['email'],
165	            $student['gender'],
166	            $student['college_name'],
167	            $student['branch'],
168	            $student['roll_number'],
169	            $student['year_of_joining'],
170	            $student['course_name'],
171	            $student['password_hash'],
172	            $student['created_at'],
173	        ]);
174	
175	        $newStudentId = (int)$pdo->lastInsertId();
176	
177	        // Delete from unverified
178	        $pdo->prepare("DELETE FROM unverified_students WHERE id = ?")->execute([$studentId]);
179	
180	        $pdo->commit();
181	    } catch (Exception $e) {
182	        $pdo->rollBack();
183	        logFailedLogin($student['email'], 'signup_unverified', 'DB error during verification: ' . $e->getMessage(), $student['name']);
184	        return ['success' => false, 'error' => 'Verification failed. Please try again.'];
185	    }
186	
187	    return ['success' => true, 'student_id' => $newStudentId];
188	}
