190	/**
191	 * Resend OTP for a student (looks up in unverified_students).
192	 */
193	function resendStudentOtp(int $studentId): array {
194	    $pdo = getDB();
195	    $stmt = $pdo->prepare("SELECT id, name, email FROM unverified_students WHERE id = ?");
196	    $stmt->execute([$studentId]);
197	    $student = $stmt->fetch();
198	
199	    if (!$student) {
200	        return ['success' => false, 'error' => 'Student not found or already verified.'];
201	    }
202	
203	    return generateStudentOtp($studentId, $student['email'], $student['name']);
204	}
