206	// ─── STUDENT AUTH ─────────────────────────────────────────
207	
208	function studentLogin(string $email, string $password): array {
209	    $pdo = getDB();
210	
211	    // 1. Check verified students table first
212	    $stmt = $pdo->prepare("SELECT * FROM students WHERE email = ?");
213	    $stmt->execute([$email]);
214	    $student = $stmt->fetch();
215	
216	    if ($student && password_verify($password, $student['password_hash'])) {
217	        $_SESSION['student_id']   = (int)$student['id'];
218	        $_SESSION['student_name'] = $student['name'];
219	        $_SESSION['student_email']= $student['email'];
220	        $_SESSION['batch_id']     = (int)$student['batch_id'];
221	        $_SESSION['role']         = 'student';
222	        session_regenerate_id(true);
223	        return ['success' => true];
224	    }
225	
226	    // 2. Check unverified_students table (registered but not verified)
227	    $stmt = $pdo->prepare("SELECT id, name, email, password_hash FROM unverified_students WHERE email = ?");
228	    $stmt->execute([$email]);
229	    $unverified = $stmt->fetch();
230	
231	    if ($unverified) {
232	        if (password_verify($password, $unverified['password_hash'])) {
233	            // Password matches — just not verified yet
234	            return [
235	                'success'    => false,
236	                'error'      => 'Please verify your email first. An OTP was sent during registration.',
237	                'not_verified' => true,
238	                'student_id'  => (int)$unverified['id'],
239	            ];
240	        }
241	        // Password doesn't match for unverified student
242	        logFailedLogin($email, 'wrong_password', 'Invalid password for unverified account.', $unverified['name']);
243	        return ['success' => false, 'error' => 'Invalid email or password.'];
244	    }
245	
246	    // 3. Not found in either table
247	    logFailedLogin($email, 'invalid_email', 'Email not registered.');
248	    return ['success' => false, 'error' => 'Invalid email or password.'];
249	}
