251	/**
252	 * Register a new student.
253	 * Inserts into unverified_students (not students table).
254	 */
255	function studentRegister(array $data): array {
256	    $pdo = getDB();
257	
258	    // Check duplicate email in both tables
259	    $stmt = $pdo->prepare("SELECT id FROM students WHERE email = ?");
260	    $stmt->execute([$data['email']]);
261	    if ($stmt->fetch()) {
262	        logFailedLogin($data['email'], 'duplicate_email', 'Email already registered (verified).');
263	        return ['success' => false, 'error' => 'Email already registered.'];
264	    }
265	
266	    $stmt = $pdo->prepare("SELECT id FROM unverified_students WHERE email = ?");
267	    $stmt->execute([$data['email']]);
268	    if ($stmt->fetch()) {
269	        logFailedLogin($data['email'], 'duplicate_email', 'Email already registered (unverified).');
270	        return ['success' => false, 'error' => 'Email already registered. Please check your email for the OTP or request a new one.'];
271	    }
272	
273	    // Validate batch belongs to course
274	    $stmt = $pdo->prepare("
275	        SELECT b.id FROM batches b
276	        JOIN courses c ON c.id = b.course_id
277	        WHERE b.id = ? AND c.id = ? AND c.college_id = ?
278	    ");
279	    $stmt->execute([$data['batch_id'], $data['course_id'], $data['college_id']]);
280	    if (!$stmt->fetch()) {
281	        return ['success' => false, 'error' => 'Invalid batch selection.'];
282	    }
283	
284	    // Get college name and course name for record
285	    $collegeStmt = $pdo->prepare("SELECT name FROM colleges WHERE id = ?");
286	    $collegeStmt->execute([$data['college_id']]);
287	    $college = $collegeStmt->fetch();
288	
289	    $courseStmt = $pdo->prepare("SELECT name FROM courses WHERE id = ?");
290	    $courseStmt->execute([$data['course_id']]);
291	    $course = $courseStmt->fetch();
292	
293	    // Insert into unverified_students
294	    $stmt = $pdo->prepare("
295	        INSERT INTO unverified_students (batch_id, name, phone, email, gender, college_name, branch, roll_number, year_of_joining, course_name, password_hash)
296	        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
297	    ");
298	    $stmt->execute([
299	        $data['batch_id'],
300	        $data['name'],
301	        $data['phone'],
302	        $data['email'],
303	        $data['gender'],
304	        $college['name'],
305	        $data['branch'],
306	        $data['roll_number'],
307	        (int)$data['year_of_joining'],
308	        $course['name'],
309	        password_hash($data['password'], PASSWORD_BCRYPT),
310	    ]);
311	
312	    $studentId = (int)$pdo->lastInsertId();
313	
314	    // Generate and send OTP
315	    $otpResult = generateStudentOtp($studentId, $data['email'], $data['name']);
316	
317	    return [
318	        'success'   => true,
319	        'student_id'=> $studentId,
320	        'otp_sent'  => $otpResult['success'],
321	        'otp_dev'   => $otpResult['otp'] ?? null, // Only in dev mode
322	    ];
323	}
