327	function isAdmin(): bool {
328	    return ($_SESSION['role'] ?? '') === 'admin' && !empty($_SESSION['admin_id']);
329	}
330	
331	function isStudent(): bool {
332	    return ($_SESSION['role'] ?? '') === 'student' && !empty($_SESSION['student_id']);
333	}
