357	// ─── GUEST ACCESS ─────────────────────────────────────────
358	
359	function guestLogin(string $token): array {
360	    $pdo = getDB();
361	    $stmt = $pdo->prepare("SELECT * FROM guest_entries WHERE token = ? AND status = 'pending' AND expires_at > NOW()");
362	    $stmt->execute([$token]);
363	    $entry = $stmt->fetch();
364	
365	    if (!$entry) {
366	        return ['success' => false, 'error' => 'Invalid or expired link.'];
367	    }
368	
369	    $testId = $entry['test_id'] ? (int)$entry['test_id'] : null;
370	    $_SESSION['guest_token'] = $token;
371	    $_SESSION['guest_entry_id'] = (int)$entry['id'];
372	    $_SESSION['batch_id'] = (int)$entry['batch_id'];
373	    $_SESSION['test_id'] = $testId;
374	    $_SESSION['role'] = 'guest';
375	
376	    return ['success' => true, 'test_id' => $testId];
377	}
